// Shared material, light, gradient and trace uniforms.
function uploadRenderUniforms(uniform,v){uniform('J',[v.VMode,v.VScale,v.Bounds,v.ViewClip]);uniform('M',[v.Metallic,v.Roughness,v.Clearcoat,0]);uniform('L',[v.KeyIntensity,v.CyanIntensity,v.RimIntensity,v.Exposure]);uniform('N',[v.KeyAzimuth,v.KeyElevation,v.EnvironmentRotation,v.Emission]);uniform('T',[0,0,0,v.StepScale]);uniform('K0',[v.GradientType,v.GradientSpace,v.GradientAngle,v.GradientGamma]);uniform('K1',[v.GradientDistort,v.GradientRadius,v.GradientTex,v.GradientInvert]);uniform('K2',[v.GradientStartX,v.GradientStartY,v.GradientStartZ,v.GradientEndX]);uniform('K3',[v.GradientEndY,v.GradientEndZ,0,0]);uniform('MG',[v.Metallic,v.Roughness,v.BlueMetallic,v.BlueRoughness]);uniform('R',[v.DetailPrecision,v.FillIntensity,v.ReflectionGain,v.LightSize]);uniform('S',[v.SpecularFill,v.ReflectionOcclusion,v.BlueBounce,v.NormalFilter]);}


